1	package indexroom
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9	)
10	
11	// ErrInvalidSnapshot marks a rejected snapshot document: malformed or
12	// truncated JSON, trailing data after the object, an unknown version,
13	// missing, mistyped, unknown, or duplicated fields, heights that do not
14	// ascend consecutively from 1, an empty or duplicated hash, a broken parent
15	// link, a version-2 timestamp that is missing or neither null nor a
16	// non-negative integer, or a tip that disagrees with the block list. A
17	// rejected restore never changes the index.
18	var ErrInvalidSnapshot = errors.New("indexroom: invalid snapshot")
19	
20	const (
21		// snapshotVersion1 is the timestamp-less layout. It stays readable
22		// indefinitely; its blocks restore with missing timestamps.
23		snapshotVersion1 = 1
24		// snapshotVersion2 adds a required timestamp field to every block:
25		// either a non-negative Unix-seconds integer or null for missing time.
26		snapshotVersion2 = 2
27	)
28	
29	// snapshotDoc is the version-1 wire form of an exported main chain.
30	type snapshotDoc struct {
31		Version int64           `json:"version"`
32		Tip     int64           `json:"tip"`
33		Blocks  []snapshotBlock `json:"blocks"`
34	}
35	
36	// snapshotBlock is the version-1 wire form of one block.
37	type snapshotBlock struct {
38		Height int64    `json:"height"`
39		Hash   string   `json:"hash"`
40		Parent string   `json:"parent"`
41		Txs    []string `json:"txs"`
42	}
43	
44	// snapshotDocV2 is the timestamp-bearing wire form.
45	type snapshotDocV2 struct {
46		Version int64             `json:"version"`
47		Tip     int64             `json:"tip"`
48		Blocks  []snapshotBlockV2 `json:"blocks"`
49	}
50	
51	// snapshotBlockV2 is the version-2 wire form of one block. A nil Timestamp
52	// serializes as null.
53	type snapshotBlockV2 struct {
54		Height    int64    `json:"height"`
55		Hash      string   `json:"hash"`
56		Parent    string   `json:"parent"`
57		Txs       []string `json:"txs"`
58		Timestamp *int64   `json:"timestamp"`
59	}
60	
61	// Export writes the current main chain to w as a JSON snapshot: a single
62	// object with version, tip, and the blocks ordered by ascending height, each
63	// carrying its transactions in order. The same main chain always produces
64	// the same bytes, regardless of the reorg, restore, or query history that
65	// led to it. Only blocks in effect at export time appear; nothing the index
66	// once held and later dropped is included.
67	//
68	// A chain whose blocks all lack timestamps keeps the original version-1
69	// layout, byte for byte. As soon as any block carries a timestamp the
70	// document is version 2 and every block includes a timestamp field: a
71	// non-negative integer or null for a missing timestamp.
72	//
73	// Export observes one complete chain state and never modifies the index.
74	// The chain is copied under the lock and serialized afterwards, so queries
75	// and appends proceed while the stream is still being written. A write
76	// failure is reported and leaves the index untouched.
77	func (index *Index) Export(w io.Writer) error {
78		index.mu.Lock()
79		version := int64(snapshotVersion1)
80		for height := int64(1); height <= index.Tip; height++ {
81			if index.Blocks[height].Time != nil {
82				version = snapshotVersion2
83				break
84			}
85		}
86		var raw []byte
87		var err error
88		if version == snapshotVersion1 {
89			doc := snapshotDoc{
90				Version: snapshotVersion1,
91				Tip:     index.Tip,
92				Blocks:  make([]snapshotBlock, 0, int(index.Tip)),
93			}
94			for height := int64(1); height <= index.Tip; height++ {
95				block := index.Blocks[height]
96				txs := make([]string, len(block.Txs))
97				copy(txs, block.Txs)
98				doc.Blocks = append(doc.Blocks, snapshotBlock{
99					Height: block.Height,
100					Hash:   block.Hash,
101					Parent: block.Parent,
102					Txs:    txs,
103				})
104			}
105			index.mu.Unlock()
106			raw, err = json.Marshal(doc)
107		} else {
108			doc := snapshotDocV2{
109				Version: snapshotVersion2,
110				Tip:     index.Tip,
111				Blocks:  make([]snapshotBlockV2, 0, int(index.Tip)),
112			}
113			for height := int64(1); height <= index.Tip; height++ {
114				block := index.Blocks[height]
115				txs := make([]string, len(block.Txs))
116				copy(txs, block.Txs)
117				entry := snapshotBlockV2{
118					Height: block.Height,
119					Hash:   block.Hash,
120					Parent: block.Parent,
121					Txs:    txs,
122				}
123				if block.Time != nil {
124					t := *block.Time
125					entry.Timestamp = &t
126				}
127				doc.Blocks = append(doc.Blocks, entry)
128			}
129			index.mu.Unlock()
130			raw, err = json.Marshal(doc)
131		}
132		if err != nil {
133			panic(err) // snapshot docs only contain marshalable fields
134		}
135		n, err := w.Write(raw)
136		if err != nil {
137			return fmt.Errorf("indexroom: export snapshot: %w", err)
138		}
139		if n != len(raw) {
140			return fmt.Errorf("indexroom: export snapshot: %w", io.ErrShortWrite)
141		}
142		return nil
143	}
144	
145	// Restore replaces the whole main chain with the snapshot read from r. The
146	// input must be exactly one snapshot object, optionally followed by
147	// whitespace; every block is validated — including heights ascending from 1,
148	// non-empty unique hashes, and parent linkage — before anything is applied.
149	// The first block's parent is exempt from linkage: it names the chain start
150	// and need not be indexed.
151	//
152	// The replacement takes effect as one complete operation: on success the
153	// index holds exactly the snapshot chain with no leftover heights or hashes,
154	// and on any failure — a read error or an invalid block discovered at the
155	// very end — the current chain and every previously issued cursor remain as
156	// they were. The stream is consumed and validated before the lock is taken,
157	// so the index stays queryable and appendable while the restore is reading.
158	//
159	// After a successful restore, cursors issued earlier by this same index keep
160	// working wherever the pinned range still matches and the tip still covers
161	// it; otherwise continuations fail with ErrQueryChanged as usual.
162	func (index *Index) Restore(r io.Reader) error {
163		tip, blocks, err := parseSnapshot(r)
164		if err != nil {
165			return err
166		}
167		stored := make(map[int64]Block, len(blocks))
168		byHash := make(map[string]int64, len(blocks))
169		for _, block := range blocks {
170			stored[block.Height] = block
171			byHash[block.Hash] = block.Height
172		}
173		index.mu.Lock()
174		index.Blocks = stored
175		index.ByHash = byHash
176		index.Tip = tip
177		index.mu.Unlock()
178		return nil
179	}
180	
181	// parseSnapshot reads and fully validates one snapshot document. It returns
182	// the tip height and the validated blocks in ascending height order.
183	func parseSnapshot(r io.Reader) (int64, []Block, error) {
184		dec := json.NewDecoder(r)
185		tok, err := dec.Token()
186		if err != nil {
187			return 0, nil, classifySnapshotErr(err)
188		}
189		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
190			return 0, nil, invalidSnapshot("snapshot must be a single JSON object")
191		}
192	
193		// Top-level fields are captured raw so blocks can be parsed with the
194		// strict schema matching the declared version, whatever the field order.
195		var (
196			version, tip         int64
197			rawBlocks            json.RawMessage
198			haveVersion, haveTip bool
199			haveBlocks           bool
200			seen                 = map[string]bool{}
201		)
202		for dec.More() {
203			key, err := snapshotKey(dec)
204			if err != nil {
205				return 0, nil, err
206			}
207			if seen[key] {
208				return 0, nil, invalidSnapshot("duplicate field %q", key)
209			}
210			seen[key] = true
211			switch key {
212			case "version":
213				if err := dec.Decode(&version); err != nil {
214					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
215				}
216				haveVersion = true
217			case "tip":
218				if err := dec.Decode(&tip); err != nil {
219					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
220				}
221				haveTip = true
222			case "blocks":
223				if err := dec.Decode(&rawBlocks); err != nil {
224					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
225				}
226				haveBlocks = true
227			default:
228				return 0, nil, invalidSnapshot("unknown field %q", key)
229			}
230		}
231		if _, err := dec.Token(); err != nil { // closing '}'
232			return 0, nil, classifySnapshotErr(err)
233		}
234		// Only whitespace may follow the snapshot object.
235		if _, err := dec.Token(); err != io.EOF {
236			if err == nil {
237				return 0, nil, invalidSnapshot("trailing data after the snapshot object")
238			}
239			return 0, nil, classifySnapshotErr(err)
240		}
241	
242		if !haveVersion {
243			return 0, nil, invalidSnapshot("missing field %q", "version")
244		}
245		if !haveTip {
246			return 0, nil, invalidSnapshot("missing field %q", "tip")
247		}
248		if !haveBlocks {
249			return 0, nil, invalidSnapshot("missing field %q", "blocks")
250		}
251		if version != snapshotVersion1 && version != snapshotVersion2 {
252			return 0, nil, invalidSnapshot("unsupported version %d", version)
253		}
254	
255		blockDec := json.NewDecoder(bytes.NewReader(rawBlocks))
256		blocks, err := parseSnapshotBlocks(blockDec, version)
257		if err != nil {
258			return 0, nil, err
259		}
260		if _, err := blockDec.Token(); err != io.EOF {
261			if err == nil {
262				return 0, nil, invalidSnapshot("trailing data after the blocks array")
263			}
264			return 0, nil, classifySnapshotErr(err)
265		}
266	
267		lastHeight := int64(0)
268		if len(blocks) > 0 {
269			lastHeight = blocks[len(blocks)-1].Height
270		}
271		if tip != lastHeight {
272			return 0, nil, invalidSnapshot("tip %d does not match the last block height %d", tip, lastHeight)
273		}
274		return tip, blocks, nil
275	}
276	
277	// parseSnapshotBlocks reads the blocks array value, validating heights,
278	// hashes, parent links, and (for version 2) timestamps as it goes.
279	func parseSnapshotBlocks(dec *json.Decoder, version int64) ([]Block, error) {
280		tok, err := dec.Token()
281		if err != nil {
282			return nil, classifySnapshotErr(err)
283		}
284		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
285			return nil, invalidSnapshot("field %q must be an array", "blocks")
286		}
287		blocks := []Block{}
288		seenHash := map[string]bool{}
289		for dec.More() {
290			var block Block
291			if version == snapshotVersion2 {
292				block, err = parseSnapshotBlockV2(dec)
293			} else {
294				block, err = parseSnapshotBlock(dec)
295			}
296			if err != nil {
297				return nil, err
298			}
299			want := int64(len(blocks) + 1)
300			if block.Height != want {
301				return nil, invalidSnapshot("block height %d out of order, expected %d", block.Height, want)
302			}
303			if block.Hash == "" {
304				return nil, invalidSnapshot("block at height %d has an empty hash", block.Height)
305			}
306			if seenHash[block.Hash] {
307				return nil, invalidSnapshot("duplicate hash %q", block.Hash)
308			}
309			seenHash[block.Hash] = true
310			// The first block's parent names the chain start and is exempt from
311			// linkage; every later block must point at its predecessor.
312			if len(blocks) > 0 && block.Parent != blocks[len(blocks)-1].Hash {
313				return nil, invalidSnapshot("block at height %d does not link to its parent", block.Height)
314			}
315			blocks = append(blocks, block)
316		}
317		if _, err := dec.Token(); err != nil { // closing ']'
318			return nil, classifySnapshotErr(err)
319		}
320		return blocks, nil
321	}
322	
323	// parseSnapshotBlock reads one version-1 block object, requiring exactly the
324	// fields height, hash, parent, and txs.
325	func parseSnapshotBlock(dec *json.Decoder) (Block, error) {
326		var block Block
327		tok, err := dec.Token()
328		if err != nil {
329			return block, classifySnapshotErr(err)
330		}
331		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
332			return block, invalidSnapshot("block must be a JSON object")
333		}
334		var haveHeight, haveHash, haveParent, haveTxs bool
335		seen := map[string]bool{}
336		for dec.More() {
337			key, err := snapshotKey(dec)
338			if err != nil {
339				return block, err
340			}
341			if seen[key] {
342				return block, invalidSnapshot("duplicate block field %q", key)
343			}
344			seen[key] = true
345			switch key {
346			case "height":
347				if err := dec.Decode(&block.Height); err != nil {
348					return block, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
349				}
350				haveHeight = true
351			case "hash":
352				if err := dec.Decode(&block.Hash); err != nil {
353					return block, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
354				}
355				haveHash = true
356			case "parent":
357				if err := dec.Decode(&block.Parent); err != nil {
358					return block, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
359				}
360				haveParent = true
361			case "txs":
362				txs, err := parseSnapshotTxs(dec)
363				if err != nil {
364					return block, err
365				}
366				block.Txs = txs
367				haveTxs = true
368			default:
369				return block, invalidSnapshot("unknown block field %q", key)
370			}
371		}
372		if _, err := dec.Token(); err != nil { // closing '}'
373			return block, classifySnapshotErr(err)
374		}
375		for field, present := range map[string]bool{
376			"height": haveHeight,
377			"hash":   haveHash,
378			"parent": haveParent,
379			"txs":    haveTxs,
380		} {
381			if !present {
382				return block, invalidSnapshot("block is missing field %q", field)
383			}
384		}
385		return block, nil
386	}
387	
388	// parseSnapshotBlockV2 reads one version-2 block object, requiring exactly
389	// the fields height, hash, parent, txs, and timestamp. Timestamp must be
390	// null or a non-negative integer; the block returns a nil time for null.
391	func parseSnapshotBlockV2(dec *json.Decoder) (Block, error) {
392		var block Block
393		tok, err := dec.Token()
394		if err != nil {
395			return block, classifySnapshotErr(err)
396		}
397		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
398			return block, invalidSnapshot("block must be a JSON object")
399		}
400		var haveHeight, haveHash, haveParent, haveTxs, haveTimestamp bool
401		seen := map[string]bool{}
402		for dec.More() {
403			key, err := snapshotKey(dec)
404			if err != nil {
405				return block, err
406			}
407			if seen[key] {
408				return block, invalidSnapshot("duplicate block field %q", key)
409			}
410			seen[key] = true
411			switch key {
412			case "height":
413				if err := dec.Decode(&block.Height); err != nil {
414					return block, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
415				}
416				haveHeight = true
417			case "hash":
418				if err := dec.Decode(&block.Hash); err != nil {
419					return block, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
420				}
421				haveHash = true
422			case "parent":
423				if err := dec.Decode(&block.Parent); err != nil {
424					return block, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
425				}
426				haveParent = true
427			case "txs":
428				txs, err := parseSnapshotTxs(dec)
429				if err != nil {
430					return block, err
431				}
432				block.Txs = txs
433				haveTxs = true
434			case "timestamp":
435				t, err := parseSnapshotTimestamp(dec)
436				if err != nil {
437					return block, err
438				}
439				block.Time = t
440				haveTimestamp = true
441			default:
442				return block, invalidSnapshot("unknown block field %q", key)
443			}
444		}
445		if _, err := dec.Token(); err != nil { // closing '}'
446			return block, classifySnapshotErr(err)
447		}
448		for field, present := range map[string]bool{
449			"height":    haveHeight,
450			"hash":      haveHash,
451			"parent":    haveParent,
452			"txs":       haveTxs,
453			"timestamp": haveTimestamp,
454		} {
455			if !present {
456				return block, invalidSnapshot("block is missing field %q", field)
457			}
458		}
459		return block, nil
460	}
461	
462	// parseSnapshotTimestamp reads one timestamp value: null for a missing
463	// timestamp, or a non-negative integer. Zero is stored as a real timestamp,
464	// distinct from null.
465	func parseSnapshotTimestamp(dec *json.Decoder) (*int64, error) {
466		var t *int64
467		if err := dec.Decode(&t); err != nil {
468			return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", "timestamp", err))
469		}
470		if t != nil && *t < 0 {
471			return nil, invalidSnapshot("timestamp must not be negative")
472		}
473		return t, nil
474	}
475	
476	// parseSnapshotTxs reads one txs array, preserving duplicates and empty
477	// identifiers exactly as written.
478	func parseSnapshotTxs(dec *json.Decoder) ([]string, error) {
479		tok, err := dec.Token()
480		if err != nil {
481			return nil, classifySnapshotErr(err)
482		}
483		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
484			return nil, invalidSnapshot("field %q must be an array of strings", "txs")
485		}
486		txs := []string{}
487		for dec.More() {
488			var tx string
489			if err := dec.Decode(&tx); err != nil {
490				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
491			}
492			txs = append(txs, tx)
493		}
494		if _, err := dec.Token(); err != nil { // closing ']'
495			return nil, classifySnapshotErr(err)
496		}
497		return txs, nil
498	}
499	
500	// snapshotKey reads the next object key.
501	func snapshotKey(dec *json.Decoder) (string, error) {
502		tok, err := dec.Token()
503		if err != nil {
504			return "", classifySnapshotErr(err)
505		}
506		key, ok := tok.(string)
507		if !ok {
508			return "", invalidSnapshot("object key must be a string")
509		}
510		return key, nil
511	}
512	
513	// invalidSnapshot builds an ErrInvalidSnapshot error with a specific reason.
514	func invalidSnapshot(format string, args ...any) error {
515		return fmt.Errorf("%w: %s", ErrInvalidSnapshot, fmt.Sprintf(format, args...))
516	}
517	
518	// classifySnapshotErr maps decoder failures onto the snapshot error model:
519	// malformed JSON, wrong value types, and truncation are snapshot errors,
520	// while anything else is an underlying read failure reported as-is.
521	func classifySnapshotErr(err error) error {
522		var syntaxErr *json.SyntaxError
523		var typeErr *json.UnmarshalTypeError
524		switch {
525		case errors.As(err, &syntaxErr), errors.As(err, &typeErr):
526			return fmt.Errorf("%w: %v", ErrInvalidSnapshot, err)
527		case errors.Is(err, io.EOF), errors.Is(err, io.ErrUnexpectedEOF):
528			return fmt.Errorf("%w: unexpected end of input", ErrInvalidSnapshot)
529		default:
530			return fmt.Errorf("indexroom: read snapshot: %w", err)
531		}
532	}
