func TestRestoreV1TreatsTimestampsAsMissing(t *testing.T) {
	v1 := `{"version":1,"tip":2,"blocks":[` +
		`{"height":1,"hash":"h1","parent":"g","txs":["a"]},` +
		`{"height":2,"hash":"h2","parent":"h1","txs":["b"]}` +
		`]}`
	index := New()
	if err := index.Restore(strings.NewReader(v1)); err != nil {
		t.Fatal(err)
	}
